import { useState, useRef, useEffect } from "react";
import Message from "./Message";
import Header from "./Header";
import { Camera, Paperclip, Smile, Send } from "lucide-react";
import { Picker } from "ms-3d-emoji-picker";
import { PlaceholdersAndVanishInput } from "@/components/ui/placeholders-and-vanish-input";

interface MessageType {
  id: number;
  text: string;
  sender: "sender" | "receiver";
  time: string;
  conversationId: string;
}

interface ChatWindowProps {
  conversation: { id: string; name: string; avatar: string };
  messages: MessageType[];
}

const ChatWindow: React.FC<ChatWindowProps> = ({
  conversation,
  conversations,
  messages: initialMessages,
}) => {
  const [messages, setMessages] = useState<MessageType[]>(initialMessages);
  const [message, setMessage] = useState<string>("");
  const [showPicker, setShowPicker] = useState<boolean>(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSend = (): void => {
    if (message.trim()) {
      const newMessage: MessageType = {
        id: messages.length + 1,
        text: message,
        sender: "sender",
        time: new Date().toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
        }),
      };
      setMessages([...messages, newMessage]);
      setMessage("");
    }
  };

  return (
    <div className="h-screen flex flex-col bg-zinc-900">
      <Header conversations={conversations} />
      <div className="flex-1 overflow-y-auto p-4">
        {messages
          .filter((msg) => msg.conversationId === conversation.id) // Filter messages
          .map((msg, index) => (
            <Message
              key={msg.id || index}
              message={msg}
              isOwnMessage={msg.sender === "sender"}
            />
          ))}
        <div ref={messagesEndRef} />
      </div>

      <div className="sticky bottom-0 border-t border-gray-700 bg-zinc-900 p-4 shadow-lg">
        <div className="flex items-center gap-3 p-4 bg-zinc-800 rounded-lg">
          <div className="relative">
            <button
              onClick={() => setShowPicker(!showPicker)}
              className="p-2 rounded-lg hover:bg-zinc-700 transition"
            >
              <Smile className="w-6 h-6 text-gray-400 hover:text-white" />
            </button>
            {showPicker && (
              <div className="absolute bottom-12 left-0 bg-zinc-800 shadow-lg rounded-lg">
                <Picker
                  isOpen={true}
                  handleEmojiSelect={(selectedEmoji: EmojiType) =>
                    console.log(selectedEmoji)
                  }
                />
              </div>
            )}
          </div>
          <label
            htmlFor="camera"
            className="cursor-pointer p-2 rounded-lg hover:bg-zinc-700 transition"
          >
            <Camera className="w-6 h-6 text-gray-400 hover:text-white" />
            <input
              type="file"
              accept="image/*"
              id="camera"
              className="hidden"
            />
          </label>
          <div className="flex-1">
            <PlaceholdersAndVanishInput
              placeholders={["Type a message..."]}
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              onSubmit={() => handleSend()}
            />
          </div>
          <button
            onClick={handleSend}
            className="p-2 rounded-lg hover:bg-zinc-700 transition"
          >
            <Send className="w-6 h-6 text-blue-500 hover:text-blue-400" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatWindow;
