import { motion } from "framer-motion";
import React from "react";

interface MessageProps {
  message: {
    id: number;
    text: string;
    sender: "sender" | "receiver";
    time: string;
    file?: {
      name: string;
      type: string;
      url: string;
    } | null;
  };
  isOwnMessage: boolean;
}

const Message: React.FC<MessageProps> = ({ message, isOwnMessage }) => {
  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3 }}
      className={`flex ${isOwnMessage ? "justify-end" : "justify-start"} my-2`}
    >
      <div className={`p-3 rounded-lg max-w-[75%] shadow-md ${isOwnMessage ? "bg-blue-500 text-white" : "bg-gray-200 text-black"}`}>
        {message.file && (
          <div className="mb-2">
            <a href={message.file.url} target="_blank" rel="noopener noreferrer">
              <img src={message.file.url} alt={message.file.name} className="w-40 rounded-md" />
            </a>
          </div>
        )}
        <p className="text-sm">{message.text}</p>
        <p className="text-xs text-gray-300 mt-1 text-right">{message.time}</p>
      </div>
    </motion.div>
  );
};

export default Message;
